func (u *ContentReferenceUpsertBulk) Update(set func(*ContentReferenceUpsert)) *ContentReferenceUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&ContentReferenceUpsert{UpdateSet: update})
	}))
	return u
}

